DECL_SUPPORT_FLAG(HcommAicpuTsTaskCacheClear);

void HcommPrimitivesDlInit(void* libHcommHandle); // 本模块独立初始化

#ifdef __cplusplus
}
#endif

#endif // HCOMM_PRIMITIVES_DL_H

