#define HCCL_LOG_PRINT(moduleId, logType, format, ...)                                                              \
    do {                                                                                                            \
        LOG_FUNC(moduleId, logType, "[%s:%d] [%u]" format, __FILE__, __LINE__, syscall(SYS_gettid), ##__VA_ARGS__); \
