102	    bool FuseNotifyToLastWriteReduceDesc(std::vector<HcclHcommBatchTransferDesc>& descs, uint32_t notifyIdx)
103	    {
104	        if (descs.empty()) {
105	            return false;
106	        }
107	        const HcclHcommBatchTransferDesc& last = descs.back();
108	        if (last.transType != HCCL_HCOMM_TRANSFER_TYPE_WRITE_REDUCE) {
109	            return false;
110	        }
111	        const auto count = last.transferInfo.reduce.count;
112	        void* dst = last.transferInfo.reduce.dst;
113	        void* src = last.transferInfo.reduce.src;
114	        const auto reduceOp = last.transferInfo.reduce.reduceOp;
115	        const auto dataType = last.transferInfo.reduce.dataType;
116	
117	        HcclHcommBatchTransferDesc fusedDesc = {};
118	        fusedDesc.transType = HCCL_HCOMM_TRANSFER_TYPE_WRITE_REDUCE_WITH_NOTIFY;
119	        fusedDesc.transferInfo.writeReduceWithNotify.count = count;
120	        fusedDesc.transferInfo.writeReduceWithNotify.dst = dst;
121	        fusedDesc.transferInfo.writeReduceWithNotify.src = src;
122	        fusedDesc.transferInfo.writeReduceWithNotify.reduceOp = reduceOp;
123	        fusedDesc.transferInfo.writeReduceWithNotify.dataType = dataType;
124	        fusedDesc.transferInfo.writeReduceWithNotify.notifyIdx = notifyIdx;
125	
126	        descs.back() = fusedDesc;
127	        HCCL_DEBUG(
128	            "[AlgDataTransWrapper] FuseNotifyToLastWriteReduceDesc: fused last descriptor to "
129	            "WRITE_REDUCE_WITH_NOTIFY, notifyIdx[%u].",
130	            notifyIdx);
131	        return true;
132	    }
