134	    template <typename ProcessSliceFunc>
135	    HcclResult RunBatchTransfer(
136	        const ThreadHandle& thread, const ChannelInfo& channel, const std::vector<DataSlice>& srcSlices,
137	        const std::vector<DataSlice>& dstSlices, const char* funcName, const char* transType,
138	        ProcessSliceFunc processSlice, bool fusePostNotify = false, uint32_t notifyIdx = 0, bool* notifyFused = nullptr)
139	    {
140	        u32 repeatNum = srcSlices.size();
141	        std::vector<HcclHcommBatchTransferDesc> transferDescs;
142	
143	        for (int i = 0; i < repeatNum; i++) {
144	            const DataSlice srcSlice = srcSlices[i];
145	            const DataSlice dstSlice = dstSlices[i];
146	            if (srcSlice.size_ == 0) {
147	                HCCL_WARNING("[AlgDataTransWrapper] %s: size is 0.", funcName);
148	                continue;
149	            }
150	            CHK_RET(processSlice(i, srcSlice, dstSlice, transferDescs, repeatNum));
151	        }
152	
153	        if (fusePostNotify && notifyFused != nullptr) {
154	            *notifyFused = FuseNotifyToLastWriteReduceDesc(transferDescs, notifyIdx);
155	        }
156	
157	        if (transferDescs.size() > 0) {
158	            TraceBatchSummary(funcName, transType, repeatNum, transferDescs.size(), channel);
159	            CHK_RET(static_cast<HcclResult>(HcclHcommBatchTransferOnThread(
160	                thread, channel.handle, transferDescs.data(), static_cast<u32>(transferDescs.size()))));
161	        }
162	        return HCCL_SUCCESS;
163	    }
