165	    template <typename ProcessSliceFunc>
166	    HcclResult RunBatchTransferAndNotify(
167	        const ThreadHandle& thread, const ChannelInfo& sendChannel, const std::vector<DataSlice>& srcSlices,
168	        const std::vector<DataSlice>& dstSlices, const char* funcName, const char* transType,
169	        ProcessSliceFunc processSlice, bool fusePostNotify)
170	    {
171	        bool notifyFused = false;
172	        CHK_RET(RunBatchTransfer(
173	            thread, sendChannel, srcSlices, dstSlices, funcName, transType, processSlice, fusePostNotify,
174	            NOTIFY_IDX_DATA_SIGNAL, &notifyFused));
175	        if (!notifyFused) {
176	            CHK_RET(static_cast<HcclResult>(
177	                HcommChannelNotifyRecordOnThread(thread, sendChannel.handle, NOTIFY_IDX_DATA_SIGNAL)));
178	        }
179	        return HCCL_SUCCESS;
180	    }
