182	    HcclResult CheckReduceSlicePair(
183	        const DataSlice& srcSlice, const DataSlice& dstSlice, HcclDataType dataType, const char* funcName)
184	    {
185	        CHK_PRT_RET(
186	            srcSlice.count_ * DATATYPE_SIZE_TABLE[dataType] != srcSlice.size_,
187	            HCCL_ERROR(
188	                "[AlgDataTransWrapper] %s: src slice count [%u] is not mate to src slice size [%u], "
189	                "dataType is [%d].",
190	                funcName, srcSlice.count_, srcSlice.size_, dataType),
191	            HcclResult::HCCL_E_INTERNAL);
192	        CHK_PRT_RET(
193	            dstSlice.count_ * DATATYPE_SIZE_TABLE[dataType] != dstSlice.size_,
194	            HCCL_ERROR(
195	                "[AlgDataTransWrapper] %s: dst slice count [%u] is not mate to dst slice size [%u], "
196	                "dataType is [%d].",
197	                funcName, dstSlice.count_, dstSlice.size_, dataType),
198	            HcclResult::HCCL_E_INTERNAL);
199	        return HCCL_SUCCESS;
200	    }
