202	    HcclResult RunWriteReduceAndNotify(
203	        const ThreadHandle& thread, const ChannelInfo& sendChannel, const std::vector<DataSlice>& srcSlices,
204	        const std::vector<DataSlice>& dstSlices, HcclDataType dataType, HcclReduceOp reduceOp, const char* funcName)
205	    {
206	        const u32 repeatNum = srcSlices.size();
207	        int lastValidIdx = -1;
208	        for (int i = 0; i < repeatNum; i++) {
209	            if (srcSlices[i].size_ != 0) {
210	                lastValidIdx = i;
211	            }
212	        }
213	        for (int i = 0; i < repeatNum; i++) {
214	            const DataSlice srcSlice = srcSlices[i];
215	            const DataSlice dstSlice = dstSlices[i];
216	            if (srcSlice.size_ == 0) {
217	                HCCL_WARNING("[AlgDataTransWrapper] %s: size is 0.", funcName);
218	                continue;
219	            }
220	            CHK_RET(CheckReduceSlicePair(srcSlice, dstSlice, dataType, funcName));
221	            void* dst = GetSliceAddr(dstSlice);
222	            void* src = GetSliceAddr(srcSlice);
223	            TraceDataSlice(
224	                funcName, "WRITE_REDUCE", i, repeatNum, srcSlice, dstSlice, src, dst, srcSlice.count_, dataType,
225	                reduceOp);
226	            if (i == lastValidIdx) {
227	                CHK_RET(static_cast<HcclResult>(HcommWriteReduceWithNotifyOnThread(
228	                    thread, sendChannel.handle, dst, src, srcSlice.count_, static_cast<HcommDataType>(dataType),
229	                    static_cast<HcommReduceOp>(reduceOp), NOTIFY_IDX_DATA_SIGNAL)));
230	            } else {
231	                CHK_RET(static_cast<HcclResult>(HcommWriteReduceOnThread(
232	                    thread, sendChannel.handle, dst, src, srcSlice.count_, static_cast<HcommDataType>(dataType),
233	                    static_cast<HcommReduceOp>(reduceOp))));
234	            }
235	        }
236	        if (lastValidIdx < 0) {
237	            CHK_RET(static_cast<HcclResult>(
238	                HcommChannelNotifyRecordOnThread(thread, sendChannel.handle, NOTIFY_IDX_DATA_SIGNAL)));
239	        }
240	        return HCCL_SUCCESS;
241	    }
242	
243	    // Template for SendRecv batch write operations (shared by SendRecvBatchWrite and SendRecvBatchWriteReduce)
244	    template <typename SendRecvInfoType, typename ProcessSliceFunc, typename FallbackFunc>
245	    HcclResult DoSendRecvBatchTx(
246	        const SendRecvInfoType& sendRecvInfo, const ThreadHandle& thread, const char* funcName, const char* transType,
247	        ProcessSliceFunc processSlice, FallbackFunc fallback, bool fusePostNotify = false)
248	    {
249	        if (!IsHcommBatchTransferOnThreadSupported()) {
250	            return fallback(sendRecvInfo, thread);
251	        }
252	        const std::vector<DataSlice> srcSlices = sendRecvInfo.sendRecvSlices_.txSlicesList_.srcSlices_;
253	        const std::vector<DataSlice> dstSlices = sendRecvInfo.sendRecvSlices_.txSlicesList_.dstSlices_;
254	        const ChannelInfo& sendChannel = sendRecvInfo.sendRecvChannels_.txChannel_;
255	        const ChannelInfo& recvChannel = sendRecvInfo.sendRecvChannels_.rxChannel_;
256	        // 向write rank发送tx同步，确保该rank的hcclBuffer可用
257	        // 这里只是在host上向device下任务，所以实际在host侧不会因为wait而阻塞
258	        CHK_RET(static_cast<HcclResult>(HcommChannelNotifyRecordOnThread(thread, recvChannel.handle, NOTIFY_IDX_ACK)));
259	        // 获取执行超时时间
260	        u32 execTimeout = ExecTimeoutManager::Instance().GetExecTimeout();
261	        CHK_RET(static_cast<HcclResult>(
262	            HcommChannelNotifyWaitOnThread(thread, sendChannel.handle, NOTIFY_IDX_ACK, execTimeout)));
263	
264	        // 写完之后做后同步告诉对面写完了
265	        CHK_RET(RunBatchTransferAndNotify(
266	            thread, sendChannel, srcSlices, dstSlices, funcName, transType, processSlice, fusePostNotify));
267	        CHK_RET(static_cast<HcclResult>(
268	            HcommChannelNotifyWaitOnThread(thread, recvChannel.handle, NOTIFY_IDX_DATA_SIGNAL, execTimeout)));
269	        return HCCL_SUCCESS;
270	    }
271	
272	    // Template for Send batch operations (shared by SendBatchWrite and SendBatchWriteReduce)
273	    template <typename DataInfoType, typename ProcessSliceFunc, typename FallbackFunc>
274	    HcclResult DoSendBatchTx(
275	        const DataInfoType& sendInfo, const ThreadHandle& thread, const char* funcName, const char* transType,
276	        ProcessSliceFunc processSlice, FallbackFunc fallback, bool fusePostNotify = false)
