344	HcclResult InitHcommBatchTransferOnThreadSupported(bool isSupported)
345	{
346	    int target = isSupported ? HCOMM_BATCH_TRANSFER_SUPPORTED : HCOMM_BATCH_TRANSFER_UNSUPPORTED;
347	    int expected = HCOMM_BATCH_TRANSFER_UNINIT;
348	    if (g_hcommBatchTransferSupportState.compare_exchange_strong(expected, target)) {
349	        return HCCL_SUCCESS;
350	    }
351	
352	    if (expected != target) {
353	        HCCL_ERROR(
354	            "[AlgDataTransWrapper] HcommBatchTransferOnThread support mismatch, cached[%d], ctx[%d].", expected,
355	            target);
356	        return HCCL_E_INTERNAL;
357	    }
358	    return HCCL_SUCCESS;
359	}
