422	/*
423	 这个SendRecv是以notify的视角去看的，针对一个thread上的notify，即有record操作也有wait操作。
424	 为什么是SendRecv：因为是一个双向的写，rank 0需要向rank 1写，而rank 1也需要向rank 0写，
425	 因此对于rank 0来说需要向rank 1 record告诉rank 1自己准备好了可以写了，
426	 而rank 0也需要wait一下rank 1的record知道rnak 1那边也可以写了。
427	*/
428	HcclResult SendRecvWrite(const SendRecvInfo& sendRecvInfo, const ThreadHandle& thread)
429	{
430	    const std::vector<DataSlice> srcSlices = sendRecvInfo.sendRecvSlices_.txSlicesList_.srcSlices_;
431	    const std::vector<DataSlice> dstSlices = sendRecvInfo.sendRecvSlices_.txSlicesList_.dstSlices_;
432	    const ChannelInfo& sendChannel = sendRecvInfo.sendRecvChannels_.txChannel_;
433	    const ChannelInfo& recvChannel = sendRecvInfo.sendRecvChannels_.rxChannel_;
434	    u32 repeatNum = srcSlices.size();
435	    // 向write rank发送tx同步，确保该rank的hcclBuffer可用
436	    // 这里只是在host上向device下任务，所以实际在host侧不会因为wait而阻塞
437	    CHK_RET(static_cast<HcclResult>(HcommChannelNotifyRecordOnThread(thread, recvChannel.handle, NOTIFY_IDX_ACK)));
438	    // 获取执行超时时间
439	    u32 execTimeout = ExecTimeoutManager::Instance().GetExecTimeout();
440	    CHK_RET(static_cast<HcclResult>(
441	        HcommChannelNotifyWaitOnThread(thread, sendChannel.handle, NOTIFY_IDX_ACK, execTimeout)));
442	    for (int i = 0; i < repeatNum; i++) {
443	        // tx同步完成后准备将自己的userIn上的数据写到对方的hcclBuffer上
444	        const DataSlice srcSlice = srcSlices[i];
445	        const DataSlice dstSlice = dstSlices[i];
446	        if (srcSlice.size_ == 0) {
447	            HCCL_WARNING("[AlgDataTransWrapper] SendRecvWrite: size is 0.");
448	            continue;
449	        }
450	        void* dst = GetSliceAddr(dstSlice);
451	        void* src = GetSliceAddr(srcSlice);
452	        TraceDataSlice(
453	            "SendRecvWrite", "WRITE", i, repeatNum, srcSlice, dstSlice, src, dst, srcSlice.size_,
454	            sendRecvInfo.dataType_, HcclReduceOp::HCCL_REDUCE_RESERVED);
455	        CHK_RET(static_cast<HcclResult>(HcommWriteOnThread(thread, sendChannel.handle, dst, src, srcSlice.size_)));
456	    }
457	    // 写完之后做后同步告诉对面写完了
458	    CHK_RET(
459	        static_cast<HcclResult>(HcommChannelNotifyRecordOnThread(thread, sendChannel.handle, NOTIFY_IDX_DATA_SIGNAL)));
460	    CHK_RET(static_cast<HcclResult>(
461	        HcommChannelNotifyWaitOnThread(thread, recvChannel.handle, NOTIFY_IDX_DATA_SIGNAL, execTimeout)));
462	    return HCCL_SUCCESS;
463	}
