930	HcclResult LocalCopySlices(
931	    const ThreadHandle& thread, const std::vector<DataSlice>& srcSlices, const std::vector<DataSlice>& dstSlices)
932	{
933	    CHK_PRT_RET(
934	        srcSlices.size() != dstSlices.size(),
935	        HCCL_ERROR(
936	            "[InsCollAlgFactory] [AlgDataTrans] LocalCopySlices: num of src slices [%u], is not equal "
937	            "to num of dst slices [%u].",
938	            srcSlices.size(), dstSlices.size()),
939	        HcclResult::HCCL_E_INTERNAL);
940	
941	    // tmpSlices: slices to be transfer in this loop
942	    DataSlice tmpSrcSlice = srcSlices[0];
943	    DataSlice tmpDstSlice = dstSlices[0];
944	
945	    for (u32 sliceIdx = 0; sliceIdx < srcSlices.size(); sliceIdx++) {
946	        if (srcSlices[sliceIdx].size_ == 0) {
947	            HCCL_WARNING("[AlgDataTransWrapper] LocalCopySlices: size is 0.");
948	            continue;
949	        }
950	        TraceDataSlice(
951	            "LocalCopySlices", "LOCAL_COPY_SLICE", sliceIdx, srcSlices.size(), srcSlices[sliceIdx], dstSlices[sliceIdx],
952	            GetSliceAddr(srcSlices[sliceIdx]), GetSliceAddr(dstSlices[sliceIdx]), srcSlices[sliceIdx].size_,
953	            HCCL_DATA_TYPE_RESERVED, HcclReduceOp::HCCL_REDUCE_RESERVED);
954	        CHK_PRT_RET(
955	            srcSlices[sliceIdx].size_ != dstSlices[sliceIdx].size_,
956	            HCCL_ERROR(
957	                "[InsCollAlgFactory] [AlgDataTransWrapper] LocalCopySlices: [%u]-th slice, src slice size [%u] "
958	                "is not equal to dst slice size [%u].",
959	                sliceIdx, srcSlices[sliceIdx].size_, dstSlices[sliceIdx].size_),
960	            HcclResult::HCCL_E_INTERNAL);
961	
962	        if (sliceIdx == (srcSlices.size() - 1)) {
963	            // last slice
964	            void* src = GetSliceAddr(tmpSrcSlice);
965	            void* dst = GetSliceAddr(tmpDstSlice);
966	            TraceDataSlice(
967	                "LocalCopySlices", "LOCAL_COPY_MERGED", sliceIdx, srcSlices.size(), tmpSrcSlice, tmpDstSlice, src, dst,
968	                tmpSrcSlice.size_, HCCL_DATA_TYPE_RESERVED, HcclReduceOp::HCCL_REDUCE_RESERVED);
969	            CHK_RET(static_cast<HcclResult>(HcommLocalCopyOnThread(thread, dst, src, tmpSrcSlice.size_)));
970	        } else if (
971	            IsContinuousSlice(srcSlices[sliceIdx + 1], tmpSrcSlice)
972	            && IsContinuousSlice(dstSlices[sliceIdx + 1], tmpDstSlice)) {
973	            // nxtSlice is continuous with tmpSlice, update tmpSlice
974	            u64 newTmpSize = tmpSrcSlice.size_ + srcSlices[sliceIdx + 1].size_;
975	            tmpSrcSlice = DataSlice(tmpSrcSlice.addr_, tmpSrcSlice.offset_, newTmpSize);
976	            tmpDstSlice = DataSlice(tmpDstSlice.addr_, tmpDstSlice.offset_, newTmpSize);
977	        } else {
978	            // nxtSlice is not continuous with tmpSlice, copy tmpSlice, update tmpSlice with nxtSlice
979	            void* src = GetSliceAddr(tmpSrcSlice);
980	            void* dst = GetSliceAddr(tmpDstSlice);
981	            TraceDataSlice(
982	                "LocalCopySlices", "LOCAL_COPY_MERGED", sliceIdx, srcSlices.size(), tmpSrcSlice, tmpDstSlice, src, dst,
983	                tmpSrcSlice.size_, HCCL_DATA_TYPE_RESERVED, HcclReduceOp::HCCL_REDUCE_RESERVED);
984	            CHK_RET(static_cast<HcclResult>(HcommLocalCopyOnThread(thread, dst, src, tmpSrcSlice.size_)));
985	
986	            tmpSrcSlice = srcSlices[sliceIdx + 1];
987	            tmpDstSlice = dstSlices[sliceIdx + 1];
988	        }
989	    }
990	
991	    return HcclResult::HCCL_SUCCESS;
992	}
993	
994	bool IsContinuousSlice(const DataSlice& nxtSlice, const DataSlice& currSlice)
995	{
996	    if (nxtSlice.addr_ != currSlice.addr_) {
997	        return false;
998	    }
999	    if (nxtSlice.offset_ != currSlice.offset_ + currSlice.size_) {
1000	        return false;
1001	    }
1002	    return true;
1003	}
