1075	// FP16: 1位符号 + 5位指数(bias=15) + 10位尾数
1076	// FP32: 1位符号 + 8位指数(bias=127) + 23位尾数
1077	float Fp16ToFp32(uint16_t fp16Bits)
1078	{
1079	    uint32_t sign = (fp16Bits >> 15) & 0x1;
1080	    uint32_t exponent = (fp16Bits >> 10) & 0x1F;
1081	    uint32_t mantissa = fp16Bits & 0x3FF;
1082	
1083	    if (exponent == 0) {
1084	        // FP16零或非规格化数（exponent=0）
1085	        if (mantissa == 0) {
1086	            // ±0: 符号位保留，指数和尾数全零
1087	            uint32_t result = sign << 31;
1088	            float f;
1089	            if (memcpy_s(&f, sizeof(f), &result, sizeof(f)) != EOK) {
1090	                HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1091	                return 0.0f;
1092	            }
1093	            return f;
1094	        }
1095	        // FP16非规格化数: 无隐含1，实际指数为-14
1096	        // 需要找到mantissa中最高有效1，将其规格化为FP32的隐含1形式
1097	        // while循环左移mantissa直到bit10=1（对应FP16隐含1的位置），shift记录左移次数
1098	        int shift = 0;
1099	        while ((mantissa & 0x400) == 0) {
1100	            mantissa <<= 1;
1101	            shift++;
1102	        }
1103	        mantissa &= 0x3FF; // 去掉隐含1，保留10位尾数
1104	        // FP32指数 = FP16实际指数(-14) + bias(127) - shift = 127 - 15 + 1 - shift
1105	        // shift越大说明原值越小，fp32Exp可能<=0，此时值太小FP32也无法表示，返回±0
1106	        int32_t fp32Exp = 127 - 15 + 1 - shift;
1107	        if (fp32Exp <= 0) {
1108	            uint32_t result = sign << 31;
1109	            float f;
1110	            if (memcpy_s(&f, sizeof(f), &result, sizeof(f)) != EOK) {
1111	                HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1112	                return 0.0f;
1113	            }
1114	            return f;
1115	        }
1116	        // 组装FP32规格化数: 符号 + 偏移后指数 + 尾数左移13位对齐到23位
1117	        uint32_t result = (sign << 31) | (static_cast<uint32_t>(fp32Exp) << 23) | (mantissa << 13);
1118	        float f;
1119	        if (memcpy_s(&f, sizeof(f), &result, sizeof(f)) != EOK) {
1120	            HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1121	            return 0.0f;
1122	        }
1123	        return f;
1124	    }
1125	    if (exponent == 0x1F) {
1126	        // FP16 Inf或NaN（exponent全1）
1127	        // mantissa==0: Inf; mantissa!=0: NaN。统一构造FP32的Inf/NaN:
1128	        // 指数=0xFF，尾数=mantissa<<13（mantissa为0时就是Inf，非0时就是NaN）
1129	        uint32_t result = (sign << 31) | (0xFF << 23) | (mantissa << 13);
1130	        float f;
1131	        if (memcpy_s(&f, sizeof(f), &result, sizeof(f)) != EOK) {
1132	            HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1133	            return 0.0f;
1134	        }
1135	        return f;
1136	    }
1137	    // FP16规格化数（1<=exponent<=30）
1138	    // FP32指数 = exponent - FP16bias(15) + FP32bias(127) = exponent + 112
1139	    // FP32尾数 = FP16尾数左移13位（10位扩展到23位，低位补零）
1140	    uint32_t result = (sign << 31) | ((exponent + 112) << 23) | (mantissa << 13);
1141	    float f;
1142	    if (memcpy_s(&f, sizeof(f), &result, sizeof(f)) != EOK) {
1143	        HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1144	        return 0.0f;
1145	    }
1146	    return f;
1147	}
1148	
1149	// FP32: 1位符号 + 8位指数(bias=127) + 23位尾数
1150	// FP16: 1位符号 + 5位指数(bias=15) + 10位尾数
1151	// FP32规格化数下溢到FP16非规格化数或±0
1152	// fp16Exp = exponent - 127 + 15 <= 0
1153	uint16_t Fp32DenormToFp16(uint32_t sign, uint32_t mantissa, int32_t fp16Exp)
1154	{
1155	    if (fp16Exp < -10) {
1156	        // 太小连FP16非规格化数都无法表示（FP16非规格化数最小有效移位为10），返回±0
1157	        return static_cast<uint16_t>(sign << 15);
1158	    }
1159	    // FP16非规格化数: 无隐含1，需要将FP32的隐含1和尾数一起右移
1160	    // totalShift = 将23位尾数移到FP16非规格化10位尾数所需的右移量
1161	    mantissa |= 0x800000; // 将隐含1放入mantissa高位
1162	    int32_t totalShift = 14 - fp16Exp;
1163	    // round-to-nearest-even舍入: 取guard bit和sticky bit
1164	    uint32_t roundBit = (mantissa >> (totalShift - 1)) & 0x1;
1165	    uint32_t truncated = mantissa & ((1U << (totalShift - 1)) - 1);
1166	    uint32_t sticky = (truncated != 0) ? 1 : 0;
1167	    uint16_t fp16Mant = static_cast<uint16_t>(mantissa >> totalShift);
1168	    fp16Mant += roundBit && (sticky || (fp16Mant & 0x1));
1169	    if (fp16Mant & 0x400) {
1170	        // 舍入进位后尾数溢出，升级为FP16最小规格化数（exponent=1, mantissa=0）
1171	        return static_cast<uint16_t>((sign << 15) | (1 << 10));
1172	    }
1173	    return static_cast<uint16_t>((sign << 15) | fp16Mant);
1174	}
1175	
1176	uint16_t Fp32ToFp16(float value)
1177	{
1178	    uint32_t fp32Bits;
1179	    if (memcpy_s(&fp32Bits, sizeof(fp32Bits), &value, sizeof(fp32Bits)) != EOK) {
1180	        HCCL_ERROR("[%s] memcpy_s failed.", __func__);
1181	        return 0;
1182	    }
1183	    uint32_t sign = (fp32Bits >> 31) & 0x1;
1184	    uint32_t exponent = (fp32Bits >> 23) & 0xFF;
1185	    uint32_t mantissa = fp32Bits & 0x7FFFFF;
1186	
1187	    if (exponent == 0) {
1188	        // FP32零或非规格化数（exponent=0），值太小无法用FP16表示，返回±0
1189	        return static_cast<uint16_t>(sign << 15);
1190	    } else if (exponent == 0xFF) {
1191	        // FP32 Inf或NaN（exponent全1）
1192	        if (mantissa == 0) {
1193	            // Inf: FP16 exponent全1 + 尾数全0
1194	            return static_cast<uint16_t>((sign << 15) | 0x7C00);
1195	        }
1196	        // NaN: FP16 exponent全1 + 尾数非零；若FP32尾数截断后为0则强制置1确保仍是NaN
1197	        uint16_t fp16Mant = static_cast<uint16_t>(mantissa >> 13);
1198	        if (fp16Mant == 0) {
1199	            fp16Mant = 1;
1200	        }
1201	        return static_cast<uint16_t>((sign << 15) | 0x7C00 | fp16Mant);
1202	    }
1203	
1204	    // FP32规格化数: 计算FP16目标指数 fp16Exp = exponent - FP32bias(127) + FP16bias(15)
1205	    int32_t fp16Exp = static_cast<int32_t>(exponent) - 127 + 15;
1206	
1207	    if (fp16Exp >= 31) {
1208	        // 上溢: 超出FP16规格化数范围（FP16最大指数=30），饱和到±Inf
1209	        return static_cast<uint16_t>((sign << 15) | 0x7C00);
1210	    } else if (fp16Exp <= 0) {
1211	        return Fp32DenormToFp16(sign, mantissa, fp16Exp);
1212	    }
1213	
1214	    // 正常规格化数: 截断23位尾数到10位，做round-to-nearest-even舍入
1215	    uint32_t discarded = mantissa & 0x1FFF; // 被丢弃的低13位
1216	    uint16_t fp16Mant = static_cast<uint16_t>(mantissa >> 13);
1217	    uint32_t roundBit = (discarded >> 12) & 0x1;   // guard bit: 被丢弃的最高位
1218	    uint32_t sticky = (discarded & 0xFFF) ? 1 : 0; // sticky bit: 被丢弃的其余位是否有1
1219	    fp16Mant += roundBit && (sticky || (fp16Mant & 0x1));
1220	    if (fp16Mant == 0x400) {
1221	        // 舍入进位导致10位尾数溢出，指数+1，尾数归零
1222	        fp16Mant = 0;
1223	        fp16Exp++;
1224	    }
1225	    if (fp16Exp >= 31) {
1226	        // 进位后指数溢出，饱和到±Inf
1227	        return static_cast<uint16_t>((sign << 15) | 0x7C00);
1228	    }
1229	    return static_cast<uint16_t>((sign << 15) | (fp16Exp << 10) | fp16Mant);
1230	}
1231	
1232	HcclResult AicpuReduceFp16(u8* dst, u8* src, u64 size, const HcclReduceOp reduceOp)
1233	{
1234	    u64 count = size / sizeof(uint16_t);
1235	    std::vector<float> srcFp32(count);
1236	    std::vector<float> dstFp32(count);
1237	    uint16_t* srcFp16 = reinterpret_cast<uint16_t*>(src);
1238	    uint16_t* dstFp16 = reinterpret_cast<uint16_t*>(dst);
1239	    for (u64 i = 0; i < count; ++i) {
1240	        srcFp32[i] = Fp16ToFp32(srcFp16[i]);
1241	        dstFp32[i] = Fp16ToFp32(dstFp16[i]);
1242	    }
1243	    HcclResult ret = AicpuReduceTemplate<float>(
1244	        dstFp32.data(), dstFp32.size() * sizeof(float), srcFp32.data(), srcFp32.size() * sizeof(float), reduceOp);
1245	    CHK_PRT_RET(
1246	        ret != HcclResult::HCCL_SUCCESS,
1247	        HCCL_ERROR("[AicpuReduceFp16] AicpuReduceTemplate failed, ret[%d].", static_cast<int>(ret)), ret);
1248	    for (u64 i = 0; i < count; ++i) {
1249	        dstFp16[i] = Fp32ToFp16(dstFp32[i]);
1250	    }
1251	    return ret;
1252	}
1253	
1254	HcclResult AicpuReduce(
1255	    const ThreadHandle& thread, const DataSlice& srcSlice, const DataSlice& dstSlice, const HcclDataType dataType,
1256	    const HcclReduceOp reduceOp)
1257	{
1258	    (void)thread;
1259	    CHK_PRT_RET(
1260	        srcSlice.size_ != dstSlice.size_,
1261	        HCCL_ERROR(
1262	            "[AlgDataTransWrapper] [AicpuReduce] AicpuReduce: src slice size [%u] "
1263	            "is not equal to dst slice size [%u].",
1264	            srcSlice.size_, dstSlice.size_),
1265	        HcclResult::HCCL_E_INTERNAL);
1266	
1267	    auto ret = HcclResult::HCCL_SUCCESS;
1268	    u8* src = static_cast<u8*>(GetSliceAddr(srcSlice));
1269	    u8* dst = static_cast<u8*>(GetSliceAddr(dstSlice));
1270	    TraceDataSlice(
1271	        "AicpuReduce", "AICPU_REDUCE", 0, 1, srcSlice, dstSlice, src, dst, srcSlice.size_, dataType, reduceOp);
1272	    switch (dataType) {
1273	        case HcclDataType::HCCL_DATA_TYPE_INT8:
1274	            ret = AicpuReduceTemplate<int8_t>(
1275	                reinterpret_cast<int8_t*>(dst), dstSlice.size_, reinterpret_cast<int8_t*>(src), srcSlice.size_,
1276	                reduceOp);
1277	            break;
1278	        case HcclDataType::HCCL_DATA_TYPE_INT32:
1279	            ret = AicpuReduceTemplate<int32_t>(
1280	                reinterpret_cast<int32_t*>(dst), dstSlice.size_, reinterpret_cast<int32_t*>(src), srcSlice.size_,
1281	                reduceOp);
1282	            break;
1283	        case HcclDataType::HCCL_DATA_TYPE_FP16:
1284	            ret = AicpuReduceFp16(dst, src, srcSlice.size_, reduceOp);
1285	            break;
1286	        case HcclDataType::HCCL_DATA_TYPE_FP32:
1287	            ret = AicpuReduceTemplate<float>(
1288	                reinterpret_cast<float*>(dst), dstSlice.size_, reinterpret_cast<float*>(src), srcSlice.size_, reduceOp);
1289	            break;
1290	        case HcclDataType::HCCL_DATA_TYPE_INT64:
1291	            ret = AicpuReduceTemplate<int64_t>(
1292	                reinterpret_cast<int64_t*>(dst), dstSlice.size_, reinterpret_cast<int64_t*>(src), srcSlice.size_,
1293	                reduceOp);
1294	            break;
1295	        case HcclDataType::HCCL_DATA_TYPE_UINT64:
1296	            ret = AicpuReduceTemplate<uint64_t>(
1297	                reinterpret_cast<uint64_t*>(dst), dstSlice.size_, reinterpret_cast<uint64_t*>(src), srcSlice.size_,
1298	                reduceOp);
1299	            break;
1300	        case HcclDataType::HCCL_DATA_TYPE_FP64:
1301	            ret = AicpuReduceTemplate<double>(
1302	                reinterpret_cast<double*>(dst), dstSlice.size_, reinterpret_cast<double*>(src), srcSlice.size_,
1303	                reduceOp);
1304	            break;
1305	        default:
1306	            HCCL_ERROR("DataType[%d] not support", int(dataType));
1307	            ret = HCCL_E_INTERNAL;
1308	            break;
1309	    }
1310	    return ret;
1311	}
1312	
1313	template <typename T>
1314	HcclResult AicpuReduceTemplate(T* dst, u64 dstSize, T* src, u64 srcSize, const HcclReduceOp reduceOp)
1315	{
1316	    if (dstSize != srcSize) {
1317	        HCCL_ERROR("srcSize[%llu] should be equal to dstSize[%llu]", srcSize, dstSize);
1318	        return HcclResult::HCCL_E_INTERNAL;
1319	    }
1320	    auto ret = HcclResult::HCCL_SUCCESS;
1321	    u64 count = dstSize / u64(sizeof(T));
1322	    for (u64 i = 0; i < count; ++i) {
1323	        T dstData = *(dst + i);
1324	        T srcData = *(src + i);
1325	        switch (reduceOp) {
1326	            case HcclReduceOp::HCCL_REDUCE_SUM:
1327	                *(dst + i) = srcData + dstData;
1328	                break;
1329	            case HcclReduceOp::HCCL_REDUCE_PROD:
1330	                if (std::is_same<T, int8_t>::value) {
1331	                    uint8_t prod = static_cast<uint8_t>(srcData) * static_cast<uint8_t>(dstData);
1332	                    *(dst + i) = static_cast<T>(prod);
1333	                } else if (std::is_same<T, int32_t>::value) {
1334	                    uint32_t prod = static_cast<uint32_t>(srcData) * static_cast<uint32_t>(dstData);
1335	                    *(dst + i) = static_cast<T>(prod);
1336	                } else {
1337	                    *(dst + i) = srcData * dstData;
1338	                }
1339	                break;
1340	            case HcclReduceOp::HCCL_REDUCE_MAX:
1341	                *(dst + i) = std::max(srcData, dstData);
1342	                break;
1343	            case HcclReduceOp::HCCL_REDUCE_MIN:
1344	                *(dst + i) = std::min(srcData, dstData);
1345	                break;
1346	            default:
1347	                HCCL_ERROR("ReduceOp[%d] not support", int(reduceOp));
1348	                ret = HcclResult::HCCL_E_INTERNAL;
1349	                break;
1350	        }
1351	    }
1352	    return ret;
1353	}
1354	
1355	} // namespace ops_hccl
