static u32 GetMaxNotifyNum(const std::vector<u32>& notifyNumPerThread, u32 initNotifyNum)
{
    u32 maxNotifyNum = initNotifyNum;
    for (u32 notifyNum : notifyNumPerThread) {
        if (notifyNum > maxNotifyNum) {
